package pricing

import java.util.concurrent.atomic.AtomicLong

data class Account(val id: String)
data class Quote(val cents: Long, val estimated: Boolean)
fun interface PriceFeed {
    suspend fun quote(account: Account): Long
}

class QuoteAction(private val feed: PriceFeed, private val completed: AtomicLong) {
    suspend fun execute(account: Account): Quote {
        val quote = try {
            Quote(feed.quote(account), estimated = false)
        } catch (failure: Exception) {
            Quote(2500, estimated = true)
        }
        completed.incrementAndGet()
        return quote
    }
}

