import javax.sql.DataSource
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

class JdbcStock(private val dataSource: DataSource) : Stock {
    private val database = Dispatchers.IO.limitedParallelism(8)

    override suspend fun reserve(tenant: String, sku: String, quantity: Int): Boolean =
        withContext(database) {
            dataSource.connection.use { connection ->
                connection.autoCommit = true
                connection.prepareStatement(
                    "UPDATE stock SET available = available - ? WHERE tenant = ? AND sku = ? AND available >= ?"
                ).use { statement ->
                    statement.setInt(1, quantity)
                    statement.setString(2, tenant)
                    statement.setString(3, sku)
                    statement.setInt(4, quantity)
                    statement.executeUpdate() == 1
                }
            }
        }
}

