package inventory

import javax.sql.DataSource
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

class JdbcStock(private val dataSource: DataSource) : Stock {
    private val database = Dispatchers.IO.limitedParallelism(8)

    override suspend fun reserve(tenant: String, sku: String, quantity: Int): Boolean =
        withContext(database) {
            dataSource.connection.use { connection ->
                connection.autoCommit = false
                try {
                    val available = connection.prepareStatement(
                        "SELECT available FROM stock WHERE tenant = ? AND sku = ?"
                    ).use { statement ->
                        statement.setString(1, tenant)
                        statement.setString(2, sku)
                        statement.executeQuery().use { rows ->
                            if (rows.next()) rows.getInt(1) else 0
                        }
                    }
                    if (available < quantity) {
                        connection.rollback()
                        false
                    } else {
                        connection.prepareStatement(
                            "UPDATE stock SET available = available - ? WHERE tenant = ? AND sku = ?"
                        ).use { statement ->
                            statement.setInt(1, quantity)
                            statement.setString(2, tenant)
                            statement.setString(3, sku)
                            check(statement.executeUpdate() == 1)
                        }
                        connection.commit()
                        true
                    }
                } catch (failure: Throwable) {
                    connection.rollback()
                    throw failure
                }
            }
        }
}

