import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class TransferService {
    private final JdbcTemplate jdbc;

    public TransferService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    @Transactional
    public void submit(String operationId, boolean rejected) {
        jdbc.update("INSERT INTO transfers(id) VALUES (?)", operationId);
        recordAttempt(operationId);
        if (rejected) throw new IllegalStateException("Transfer rejected");
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void recordAttempt(String operationId) {
        jdbc.update("INSERT INTO attempts(id) VALUES (?)", operationId);
    }
}

