package example;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;

@Component
public class BillingListener {
    private static final System.Logger LOG = System.getLogger(BillingListener.class.getName());
    private final HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();
    private final URI endpoint;

    public BillingListener(@Value("${billing.url}") URI endpoint) { this.endpoint = endpoint; }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void created(InvoiceService.Created event) {
        var request = HttpRequest.newBuilder(endpoint).timeout(Duration.ofSeconds(2))
                .header("Idempotency-Key", event.invoiceId())
                .POST(HttpRequest.BodyPublishers.ofString(event.invoiceId())).build();
        try {
            var response = client.send(request, HttpResponse.BodyHandlers.discarding());
            if (response.statusCode() / 100 != 2) LOG.log(System.Logger.Level.WARNING, "Billing unavailable");
        } catch (InterruptedException failure) {
            Thread.currentThread().interrupt();
        } catch (IOException failure) {
            LOG.log(System.Logger.Level.WARNING, "Billing unavailable");
        }
    }
}

