package reports

import io.ktor.server.application.*
import io.ktor.server.auth.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.HttpStatusCode

class Reports {
    private val rows = mapOf("weekly" to "Internal weekly summary")
    fun list(): String = rows.keys.sorted().joinToString("
")
    fun get(id: String): String? = rows[id]
}

fun Application.reportModule(accessToken: String, reports: Reports) {
    require(accessToken.length >= 32)
    install(Authentication) {
        bearer("staff") {
            authenticate { credentials ->
                if (credentials.token == accessToken) UserIdPrincipal("staff") else null
            }
        }
    }
    routing {
        authenticate("staff") {
            get("/reports") { call.respondText(reports.list()) }
        }
        get("/reports/{id}") {
            val report = reports.get(call.parameters["id"].orEmpty())
            if (report == null) call.respond(HttpStatusCode.NotFound)
            else call.respondText(report)
        }
    }
}

fun main() {
    val token = requireNotNull(System.getenv("REPORT_ACCESS_TOKEN"))
    embeddedServer(Netty, host = "127.0.0.1", port = 8080) {
        reportModule(token, Reports())
    }.start(wait = true)
}

