package catalog

import javax.sql.DataSource
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import io.ktor.http.HttpStatusCode
import io.ktor.server.application.*
import io.ktor.server.response.*
import io.ktor.server.routing.*

fun interface Catalog {
    suspend fun title(id: Int): String?
}
class JdbcCatalog(private val source: DataSource) : Catalog {
    private val database = Dispatchers.IO.limitedParallelism(4)
    override suspend fun title(id: Int): String? = withContext(database) {
        source.connection.use { connection ->
            connection.prepareStatement("SELECT title FROM catalog WHERE id = ?").use { statement ->
                statement.setInt(1, id)
                statement.executeQuery().use { rows -> if (rows.next()) rows.getString(1) else null }
            }
        }
    }
}

fun Application.catalogModule(catalog: Catalog) {
    routing {
        get("/catalog/{id}") {
            val id = call.parameters["id"]?.toIntOrNull()?.takeIf { it > 0 }
            if (id == null) {
                call.respond(HttpStatusCode.BadRequest)
                return@get
            }
            val title = catalog.title(id)
            if (title == null) call.respond(HttpStatusCode.NotFound)
            else call.respondText(title)
        }
    }
}

