package samples

import com.zaxxer.hikari.HikariConfig
import com.zaxxer.hikari.HikariDataSource
import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit

fun Application.samplerModule(jdbcUrl: String) {
    val pool = HikariDataSource(HikariConfig().apply {
        this.jdbcUrl = jdbcUrl
        maximumPoolSize = 1
        connectionTimeout = 1000
        addDataSourceProperty("socketTimeout", "3")
        addDataSourceProperty("options", "-c statement_timeout=2000")
    })
    val executor = Executors.newSingleThreadScheduledExecutor()
    val logger = log
    val scheduled = executor.scheduleWithFixedDelay({
        try {
            pool.connection.use { connection ->
                connection.createStatement().use { statement ->
                    statement.executeUpdate("INSERT INTO samples(captured_at) VALUES (CURRENT_TIMESTAMP)")
                }
            }
        } catch (failure: Exception) {
            logger.warn("Sample collection failed")
        }
    }, 0, 10, TimeUnit.SECONDS)
    environment.monitor.subscribe(ApplicationStopping) {
        pool.close()
        scheduled.cancel(false)
        executor.shutdown()
        if (!executor.awaitTermination(4, TimeUnit.SECONDS)) executor.shutdownNow()
    }
}

fun main() {
    val jdbcUrl = requireNotNull(System.getenv("SAMPLE_JDBC_URL"))
    embeddedServer(Netty, host = "127.0.0.1", port = 8080) {
        samplerModule(jdbcUrl)
    }.start(wait = true)
}

