from dataclasses import dataclass
import json
from threading import RLock
import time


TOOL = {
    "type": "function", "name": "set_shipping_draft", "strict": True,
    "description": "Set the delivery address on a session draft.",
    "parameters": {"type": "object", "additionalProperties": False,
                   "properties": {"order_id": {"type": "string"},
                                  "address": {"type": "string"}},
                   "required": ["order_id", "address"]},
}


@dataclass(frozen=True)
class Context:
    principal: str
    tenant: str
    can_edit: bool
    approval_id: str


@dataclass(frozen=True)
class Approval:
    principal: str
    tenant: str
    tool: str
    order_id: str
    address: str
    expires_at: float


@dataclass
class Draft:
    tenant: str
    address: str


class DraftExecutor:
    def __init__(self, drafts: dict[str, Draft], approvals: dict[str, Approval]):
        self._drafts = drafts
        self._approvals = approvals
        self._lock = RLock()

    def execute(self, arguments: object, context: Context) -> dict:
        if not isinstance(arguments, dict) or set(arguments) != {"order_id", "address"}:
            return {"error": "invalid_input", "effect_state": "not_started"}
        order_id, address = arguments["order_id"], arguments["address"]
        if not isinstance(order_id, str) or not 1 <= len(order_id) <= 80:
            return {"error": "invalid_input", "effect_state": "not_started"}
        if not isinstance(address, str) or not 1 <= len(address.strip()) <= 200:
            return {"error": "invalid_input", "effect_state": "not_started"}
        address = address.strip()
        with self._lock:
            draft = self._drafts.get(order_id)
            if not context.can_edit or draft is None or draft.tenant != context.tenant:
                return {"error": "denied", "effect_state": "not_started"}
            approved = self._approvals.get(context.approval_id)
            if approved is None or approved.expires_at <= time.time():
                return {"error": "approval_required", "effect_state": "not_started"}
            if (approved.principal, approved.tenant, approved.tool, approved.order_id) != (
                context.principal, context.tenant, "set_shipping_draft", order_id
            ):
                return {"error": "approval_required", "effect_state": "not_started"}
            draft.address = address
            return {"result": "updated", "effect_state": "committed"}


def function_output(call: dict, context: Context, executor: DraftExecutor) -> dict:
    if call["name"] != "set_shipping_draft":
        outcome = {"error": "unknown_tool", "effect_state": "not_started"}
    elif len(call["arguments"].encode("utf-8")) > 2048:
        outcome = {"error": "invalid_input", "effect_state": "not_started"}
    else:
        try:
            arguments = json.loads(call["arguments"])
        except (ValueError, RecursionError):
            outcome = {"error": "invalid_input", "effect_state": "not_started"}
        else:
            outcome = executor.execute(arguments, context)
    return {"type": "function_call_output", "call_id": call["call_id"],
            "output": json.dumps(outcome)}

