from dataclasses import dataclass
import json


TOOL = {
    "name": "list_note_titles",
    "description": "List up to ten note titles visible to the authenticated tenant.",
    "inputSchema": {"type": "object", "additionalProperties": False,
                    "properties": {"limit": {"type": "integer", "minimum": 1, "maximum": 10}},
                    "required": ["limit"]},
    "outputSchema": {"type": "object", "additionalProperties": False,
                     "properties": {"titles": {"type": "array", "maxItems": 10,
                                               "items": {"type": "string", "maxLength": 80}}},
                     "required": ["titles"]},
    "annotations": {"readOnlyHint": True, "destructiveHint": False},
}


@dataclass(frozen=True)
class Context:
    principal: str
    tenant: str
    can_read_notes: bool


@dataclass(frozen=True)
class Note:
    tenant: str
    title: str


def protocol_error(request_id: str | int, code: int, message: str) -> dict:
    return {"jsonrpc": "2.0", "id": request_id,
            "error": {"code": code, "message": message}}


def tool_error(request_id: str | int, message: str) -> dict:
    return {"jsonrpc": "2.0", "id": request_id,
            "result": {"isError": True, "content": [{"type": "text", "text": message}]}}


def tool_call(request: dict, context: Context, notes: tuple[Note, ...]) -> dict:
    request_id = request["id"]
    params = request.get("params")
    if request.get("method") != "tools/call" or not isinstance(params, dict):
        return protocol_error(request_id, -32600, "Invalid request")
    if params.get("name") != TOOL["name"]:
        return protocol_error(request_id, -32602, "Unknown tool")
    arguments = params.get("arguments", {})
    if not isinstance(arguments, dict):
        return protocol_error(request_id, -32602, "Arguments must be an object")
    if set(arguments) != {"limit"}:
        return tool_error(request_id, "Supply only the required limit argument")
    limit = arguments["limit"]
    if type(limit) not in (int, float) or not 1 <= limit <= 10 or limit != int(limit):
        return tool_error(request_id, "limit must be an integer between 1 and 10")
    if not context.can_read_notes:
        result = {"isError": True, "content": [{"type": "text", "text": "Not authorized"}]}
    else:
        titles = []
        for note in notes:
            if note.tenant == context.tenant:
                titles.append(note.title)
                if len(titles) == limit:
                    break
        output = {"titles": titles}
        result = {"isError": False, "structuredContent": output,
                  "content": [{"type": "text", "text": json.dumps(output)}]}
    return {"jsonrpc": "2.0", "id": request_id, "result": result}

