from dataclasses import dataclass
import json
from typing import Literal


EffectState = Literal["not_started", "not_committed", "committed", "unknown"]


@dataclass(frozen=True)
class Outcome:
    call_id: str
    execution_id: str
    effect_state: EffectState
    public_result: dict[str, str]


def outputs_for_response(response: dict, outcomes: dict[str, Outcome]) -> list[dict]:
    outputs = []
    for item in response["output"]:
        if item["type"] != "function_call":
            continue
        outcome = outcomes[item["call_id"]]
        if outcome.call_id != item["call_id"]:
            raise ValueError("Outcome does not match call")
        outputs.append({
            "type": "function_call_output",
            "call_id": item["id"],
            "output": json.dumps({"effect_state": outcome.effect_state,
                                  "result": outcome.public_result}),
        })
    return outputs
